reducer_source:
module repeat_checker #(parameter integer W = 3)(input logic clk, rst_n, start, ready);
  a: assume property (@(posedge clk) disable iff (!rst_n)
      start |=> !ready[*W] ##1 ready);
endmodule
module test;
  logic clk, rst_n, start, ready;
  repeat_checker #(.W(2)) c2(.*);
  repeat_checker #(.W(3)) c3(.*);
endmodule

